<section class="page-hero compact"><p class="eyebrow">MY ARCHON</p><h1>Hello, <?=Security::e($customer['name'])?>.</h1><p>Manage your purchases and reading library.</p></section><section class="section dashboard"><aside class="account-nav"><a class="active" href="/account">Overview</a><a href="/account/profile">Profile & security</a><a href="/account/wishlist">Wishlist</a><a href="/ebooks">Browse eBooks</a><form action="/logout" method="post"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><button>Sign out</button></form></aside><div><h2>My downloads</h2><?php if($downloads):?><div class="download-list"><?php foreach($downloads as $d):?><article><div><b><?=Security::e($d['title'])?></b><small><?=$d['download_count']?> / <?=$d['max_count']?> downloads used</small></div><?php if(strtotime($d['expires_at'])>time()&&$d['download_count']<$d['max_count']):?><a class="button small" href="/download/<?=Security::e($d['token'])?>">Download</a><?php else:?><span class="expired">Expired</span><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty"><p>Your completed purchases will appear here.</p><a class="button" href="/ebooks">Browse eBooks</a></div><?php endif;?><h2>Order history</h2><div class="table-wrap"><table><thead><tr><th>Order</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $order):?><tr><td><?=Security::e($order['order_number'])?></td><td><?=date('M j, Y',strtotime($order['created_at']))?></td><td><span class="status <?=Security::e($order['payment_status'])?>"><?=Security::e($order['order_status'])?></span></td><td>$<?=number_format((float)$order['total'],2)?></td></tr><?php endforeach;?></tbody></table></div><h2>My reviews</h2><?php if($reviews):?><div class="review-list"><?php foreach($reviews as $review):?><article><div><a href="/ebooks/<?=Security::e($review['slug'])?>"><b><?=Security::e($review['title'])?></b></a><span class="status <?=Security::e($review['status'])?>"><?=Security::e($review['status'])?></span></div><p><?=Security::e($review['body'])?></p></article><?php endforeach;?></div><?php else:?><p class="small-note">Your submitted reviews will appear here.</p><?php endif;?></div></section>
